#![cfg(target_os="linux")]
use std::{fs,path::PathBuf};
use ulmdb::{Environment,PreviousSession,ReadTxn,PublicationMode,ResidencyPolicy,ReadAhead,PageSize,DatabaseKind,CommitIntent,backup};
struct Dir(PathBuf);impl Dir{fn new()->Self{Self(std::env::temp_dir().join(format!("external-previous-{:032x}",ulmdb_storage::new_identity().unwrap())))}}impl Drop for Dir{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn create(p:&std::path::Path,m:PublicationMode)->Environment{Environment::create_externally_synchronized(p,m,PageSize::DEFAULT,ResidencyPolicy::Demand,ReadAhead::Normal,None,Default::default()).unwrap()}
#[test]fn actual_previous_owner_prepare_abort_publish_and_rollback_keep_real_history_and_burned_ids(){for mode in [PublicationMode::Legacy,PublicationMode::Cohort,PublicationMode::Indexed]{let p=Dir::new();let e=create(&p.0,mode);let mut w=e.begin_write().unwrap();w.create_database(b"kv",DatabaseKind::Kv).unwrap();w.put(b"kv",b"k",b"A").unwrap();w.commit().unwrap();let a=e.begin_read();let acp=a.file_checkpoint().unwrap();let mut w=e.begin_write().unwrap();w.put(b"kv",b"k",b"B").unwrap();w.create_database(b"undone",DatabaseKind::Kv).unwrap();let burned=w.open_database(b"undone").unwrap().id();w.commit().unwrap();let b=e.begin_read();let bcp=b.file_checkpoint().unwrap();drop(e);
 let ctx=ulmdb::ExternalSynchronization::open_namespace(&p.0,None).unwrap();let capture=ctx.capture_previous(None).unwrap();assert_eq!(*capture.selected_checkpoint(),bcp);assert_eq!(*capture.view_checkpoint(),acp);let old=capture.admit(ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();assert_eq!(old.get(b"kv",b"k").unwrap(),Some(b"A".as_slice()));
 let session=PreviousSession::open_externally_synchronized(&p.0,ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();assert_eq!(session.selected_checkpoint().unwrap(),bcp);let mut w=session.begin_write().unwrap();w.put(b"kv",b"k",b"discard").unwrap();let pending=w.prepare().unwrap();drop(pending);assert!(session.is_previous());assert_eq!(ReadTxn::open_externally_synchronized(&p.0).unwrap().get(b"kv",b"k").unwrap(),Some(b"B".as_slice()));let mut w=session.begin_write().unwrap();w.put(b"kv",b"k",b"C").unwrap();w.create_database(b"after",DatabaseKind::Kv).unwrap();assert!(w.open_database(b"after").unwrap().id()>burned);w.prepare_with_intent(CommitIntent::ForcePublication).unwrap().commit().unwrap();assert!(!session.is_previous());assert_eq!(old.get(b"kv",b"k").unwrap(),Some(b"A".as_slice()));assert_eq!(b.get(b"kv",b"k").unwrap(),Some(b"B".as_slice()));let e=session.into_environment().ok().unwrap();let c=e.begin_read();assert_eq!(c.sequence(),2);assert_eq!(c.get(b"kv",b"k").unwrap(),Some(b"C".as_slice()));assert_eq!(backup::verify(&e).unwrap().sequence,2);let cp=ulmdb_storage::read_previous(&p.0).unwrap().unwrap();assert_eq!(ulmdb_storage::checkpoint_bytes(&cp).unwrap(),acp);
 let mut w=e.begin_write().unwrap();w.put(b"kv",b"k",b"D").unwrap();w.commit().unwrap();assert_eq!(e.rollback_last_commit(3).unwrap().sequence,2);assert_eq!(e.begin_read().get(b"kv",b"k").unwrap(),Some(b"C".as_slice()));assert_eq!(c.get(b"kv",b"k").unwrap(),Some(b"C".as_slice()));assert!(!p.0.join(".ulmdb-coordination").exists());drop(e);let e=Environment::open_externally_synchronized(&p.0).unwrap();assert_eq!(e.begin_read().get(b"kv",b"k").unwrap(),Some(b"C".as_slice()));assert!(e.rollback_last_commit(2).is_err());
 }}
#[test]fn previous_genuine_genesis_and_missing_history_boundaries(){for m in [PublicationMode::Legacy,PublicationMode::Cohort,PublicationMode::Indexed]{let p=Dir::new();let e=create(&p.0,m);drop(e);let s=PreviousSession::open_externally_synchronized(&p.0,ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();let mut w=s.begin_write().unwrap();w.create_database(b"kv",DatabaseKind::Kv).unwrap();w.put(b"kv",b"k",b"first").unwrap();w.commit().unwrap();let e=s.into_environment().ok().unwrap();assert_eq!(e.begin_read().sequence(),1);assert!(!p.0.join(".ulmdb-coordination").exists());}}
